{
  "selections": [
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '이미 방향이 정해진 상태에서 물어본 것'이 아닌지 묻는 발화는, 내담자의 '내 판단이 기준이 되어야 한다'는 규칙과 직접 연결됨. 내담자가 '물어보긴 했다'고 주장하는 방식 자체가 이미 결론을 정해놓고 통보하는 형태였을 가능성을 상담사가 짚고 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/childhood_data"],
      "relevance": "'사람들은 내 방식에 토를 달지 못하고 나를 따를 것'이라는 가정이, 아내가 '괜찮다'고 말한 것을 진짜 동의라고 해석하는 내담자의 인식과 연결됨. 반대할 여지가 없다는 걸 인식하지 못하는 것이 이 가정의 작동 방식."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/2"],
      "relevance": "'싫은 게 있으면 그때 말했어야죠'라는 내담자의 반응은, 관계 문제의 원인을 상대의 수동성에서 찾는 대처 전략과 직접 일치. 상담사가 이 패턴을 gently 되비추고 있는 상황."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "특권의식/과대성 스키마가 가족 관계에서 '내가 정하면 그게 기준'이라는 방식으로 작동하며, 아내가 들러리로 느껴졌다는 통보가 이 스키마를 위협하고 있음. 상담사가 그 작동 방식을 구체적으로 드러내려는 중."
    }
  ]
}

